        }

        private async Task ReconcileFromExchangeItemSpendMasterItems(IList<EzRateModel> items, bool attachChildSubscribe, CancellationToken cancellationToken)
        {
            var seen = new HashSet<string>();
            foreach (var item in items)
            {
                if (_disposed) return;
                var rowKey = ExtractExchangeItemSpendMasterRowKey(item);
                if (rowKey == null) continue;
                seen.Add(rowKey);
                if (_bindersByRowKey.TryGetValue(rowKey, out var existing))
                {
                    ApplyExchangeItemSpendMasterItemTo(existing.MutableModel, item);
                }
                else
                {
                    var binder = await BuildBinderFromExchangeItemSpendMasterItem(item, cancellationToken);
                    if (_disposed)
                    {
                        binder.Dispose();
                        return;
                    }
                    if (_bindersByRowKey.TryGetValue(rowKey, out var raced))
                    {
                        ApplyExchangeItemSpendMasterItemTo(raced.MutableModel, item);
                        binder.Dispose();
                        continue;
                    }
                    if (attachChildSubscribe) binder.Subscribe(_onChange);
                    _bindersByRowKey[rowKey] = binder;
                    _binders.Add(binder);
                    ItemAdded?.Invoke(binder);
                }
            }
            if (_bindersByRowKey.Count > seen.Count)
            {
                var toRemove = new List<string>();
                foreach (var kv in _bindersByRowKey)
                {
                    if (!seen.Contains(kv.Key)) toRemove.Add(kv.Key);
                }
                // Detach every stale binder before callbacks; a callback may dispose this Collection.
                var pendingRemovals = new List<Action>();
                foreach (var rowKey in toRemove)
                {
                    if (!_bindersByRowKey.TryGetValue(rowKey, out var binder)) continue;
                    _bindersByRowKey.Remove(rowKey);
                    _binders.Remove(binder);
                    var detachedBinder = binder;
                    // Notify while the binder is live; the Collection retains disposal ownership.
                    pendingRemovals.Add(() =>
                    {
                        try
                        {
                            if (!_disposed) ItemRemoved?.Invoke(detachedBinder);
                        }
                        finally
                        {
                            detachedBinder.Dispose();
                        }
                    });
                }
                Exception? removalError = null;
                foreach (var remove in pendingRemovals)
                {
                    try { remove(); }
                    catch (Exception ex) { removalError ??= ex; }
                }
                if (removalError != null) throw removalError;
            }
            if (!_disposed) SortBinders();
        }

        private async Task<ItemBinder> BuildBinderFromExchangeItemSpendMasterItem(EzRateModel item, CancellationToken cancellationToken)
        {
            var model = ItemBinder.CreateModel((string.IsNullOrEmpty(item.Name) ? default(ItemId) : new ItemId(item.Name)));
            ApplyExchangeItemSpendMasterItemTo(model, item);
            var binder = new ItemBinder(model, _gs2, _session);
            await binder.MountAsync(cancellationToken);
            return binder;
        }

        private static void ApplyExchangeItemSpendMasterItemTo(MutableItem model, EzRateModel item)
        {
            // This loader carries no master-item field assignments; reconcile manages
            // membership only (per-element field changes are tracked by each element
            // binder's own Subscribe).
            _ = item;
            _ = model;
        }

        private ItemId ExtractExchangeItemSpendMasterIdentity(EzRateModel item)
        {
            return (string.IsNullOrEmpty(item.Name) ? default(ItemId) : new ItemId(item.Name));
        }

        private string? ExtractExchangeItemSpendMasterRowKey(EzRateModel item)
        {
            var id = ExtractExchangeItemSpendMasterIdentity(item);
            if (EqualityComparer<ItemId>.Default.Equals(id, default)) return null;
            if (string.IsNullOrEmpty(item.Name)) return null;
            return $"{item.Name}";
        }
