        internal sealed class ItemBinderComparer : IComparer<IReadOnlyItemBinder>
        {
            public static readonly ItemBinderComparer Default = new ItemBinderComparer();
            public int Compare(IReadOnlyItemBinder? a, IReadOnlyItemBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                return Comparer<ItemId>.Default.Compare(a.Id, b.Id);
            }
        }

        internal sealed class ItemBinderIdTieBreakComparer : IComparer<IReadOnlyItemBinder>
        {
            private readonly IComparer<IReadOnlyItemBinder> _inner;
            public ItemBinderIdTieBreakComparer(IComparer<IReadOnlyItemBinder> inner) { _inner = inner; }
            public int Compare(IReadOnlyItemBinder? a, IReadOnlyItemBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                var c = _inner.Compare(a, b);
                if (c != 0) return c;
                return Comparer<ItemId>.Default.Compare(a.Id, b.Id);
            }
        }
    }
